<template>
  <div class="audio-import">
    <label class="audio-drop" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="drop">
      <strong>{{$t(busy?'Convirtiendo audio…':'Subir o arrastrar un audio')}}</strong>
      <span>{{ $t("WAV, MP3, M4A, OGG o FLAC · conversión automática") }}</span>
      <input type="file" accept="audio/*,.wav,.flac,.m4a,.ogg" :disabled="disabled||busy" @change="upload" />
    </label>
    <div v-if="source" class="trim-editor">
      <header><strong>{{source.name}}</strong><span>{{duration.toFixed(3)}} {{ $t("s ·") }} {{$t(source.conversion)}}</span></header>
      <p>{{ $t("La onda muestra el audio resultante. Azul: recorta. Rojo: cambia la duración sin cambiar el tono.") }}</p>
      <div class="trim-track" ref="track">
        <canvas ref="wave" width="1200" height="140" role="img" :aria-label="$t(&quot;Forma de onda del audio subido&quot;)" />
        <div class="dim left" :style="{width:Math.max(0,Math.min(100,percent(start)))+'%'}"></div><div class="dim right" :style="{left:Math.max(0,Math.min(100,percent(end)))+'%'}"></div>
        <div class="trim-selection" :style="{left:percent(start)+'%',width:percentLength(outputDuration)+'%'}" @pointerdown="begin($event,'move')" @pointermove="move" @pointerup="finish" @pointercancel="finish" role="button" tabindex="0" :aria-label="$t(&quot;Mover recorte&quot;)" @keydown.left.prevent="shift(-.01)" @keydown.right.prevent="shift(.01)"></div>
        <button class="trim-handle start" :style="{left:'clamp(10px,'+percent(start)+'%,calc(100% - 10px))'}" @pointerdown="begin($event,'start')" @pointermove="move" @pointerup="finish" @pointercancel="finish" @keydown.left.prevent="step('start',-.01)" @keydown.right.prevent="step('start',.01)" role="slider" :aria-label="$t(&quot;Inicio del recorte&quot;)" :aria-valuemin="0" :aria-valuemax="end" :aria-valuenow="start" :aria-valuetext="$t(start.toFixed(3)+' segundos')">⠿</button>
        <button class="trim-handle end" :style="{left:'clamp(10px,'+percent(end)+'%,calc(100% - 10px))'}" @pointerdown="begin($event,'end')" @pointermove="move" @pointerup="finish" @pointercancel="finish" @keydown.left.prevent="step('end',-.01)" @keydown.right.prevent="step('end',.01)" role="slider" :aria-label="$t(&quot;Fin del recorte&quot;)" :aria-valuemin="start" :aria-valuemax="duration" :aria-valuenow="end" :aria-valuetext="$t(end.toFixed(3)+' segundos')">⠿</button>
        <span class="lane-label trim-label">{{ $t("Recorte") }}</span>
        <div v-if="duration*stretch<timelineDuration-minimum" class="free-space" :style="{left:outputPercent(duration*stretch)+'%',width:percentLength(timelineDuration-duration*stretch)+'%'}"><span>{{ $t("Espacio libre") }}</span></div>
        <div class="stretch-capacity-line" :style="{left:outputPercent(start*stretch+maxDuration)+'%'}"><span>{{ $t("Límite ROM") }}</span></div>
        <div class="stretch-wave" :class="{overflow:outputDuration>maxDuration}" :style="{left:percent(start)+'%',width:percentLength(outputDuration)+'%'}">
          <span class="lane-label stretch-label">Stretch · {{outputDuration.toFixed(3)}} s</span>
        </div>
        <button class="stretch-handle" :style="{left:'clamp(14px,'+percent(end)+'%,calc(100% - 14px))'}" @pointerdown="beginStretch" @pointermove="moveStretch" @pointerup="finishStretch" @pointercancel="finishStretch" @keydown.left.prevent="setStretch(stretch-.01)" @keydown.right.prevent="setStretch(stretch+.01)" role="slider" :aria-label="$t('Stretch · duración (%)')" :aria-valuemin="10" :aria-valuemax="200" :aria-valuenow="Math.round(stretch*100)">↔</button>
      </div>
      <p class="duration-summary"><strong>{{(end-start).toFixed(3)}} s</strong> {{ $t("de audio original") }} <span aria-hidden="true">→</span> <strong>{{outputDuration.toFixed(3)}} s</strong> {{ $t("en la ROM") }}</p>
      <div class="time-axis"><span>{{viewStart.toFixed(3)}} {{ $t("s") }}</span><span>{{(viewStart+viewSpan).toFixed(3)}} {{ $t("s") }}</span></div>
      <div class="view-controls"><button @click="zoom">{{ $t("Acercar al recorte") }}</button><button @click="overview">{{ $t("Ver audio completo") }}</button><label v-if="viewSpan<timelineDuration">{{ $t("Mover vista") }} <input type="range" min="0" :max="timelineDuration-viewSpan" :step="minimum" v-model.number="viewStart" @input="draw" :aria-label="$t(&quot;Desplazar vista del audio&quot;)" /></label></div>
      <div class="trim-controls">
        <label>{{ $t("Inicio (s)") }} <input type="number" min="0" :max="end-minimum" step="0.001" :value="start.toFixed(3)" @change="setStart(Number($event.target.value));commit()" /></label>
        <label>{{ $t("Fin (s)") }} <input type="number" :min="start+minimum" :max="duration" step="0.001" :value="end.toFixed(3)" @change="setEnd(Number($event.target.value));commit()" /></label>
        <label>{{ $t("Stretch · duración (%)") }} <input type="number" min="10" max="200" step="1" :value="Math.round(stretch*100)" @change="setStretch(Number($event.target.value)/100)" /></label>
        <button @click="fit">{{ $t("Ajustar a capacidad") }}</button><button @click="full" :disabled="duration>selectionCapacity">{{ $t("Audio completo") }}</button>
      </div>
      <p>{{ $t("Comprimir permite incluir más audio original en el mismo espacio. El tono se conserva.") }}</p>
      <div class="stretch-actions"><button @click="setStretch(1)">{{ $t("Restablecer 100 %") }}</button><button @click="fitStretch">{{ $t("Stretch para encajar en ROM") }}</button><span class="stretch-value">{{Math.round(stretch*100)}} % · {{outputDuration.toFixed(3)}} s</span></div>
      <p v-if="outputDuration>maxDuration" class="stretch-warning" role="status">{{ $t("El resultado supera el espacio disponible. Contrae el audio o ajusta el recorte antes de aplicar.") }}</p>
      <div class="trim-capacity"><span :style="{width:Math.min(100,outputDuration/maxDuration*100)+'%'}"></span></div>
      <p class="trim-status">{{ $t("Selección:") }} <strong>{{outputDuration.toFixed(3)}} {{ $t("s") }}</strong> / {{maxDuration.toFixed(3)}} {{ $t("s disponibles ·") }} {{$t(Math.round(outputDuration/maxDuration*100))}}{{ $t("% de capacidad") }}</p>
      <p v-if="duration>selectionCapacity&&outputDuration<=maxDuration" class="trim-hint">{{ $t("Se seleccionó un fragmento que cabe en la ROM. Puedes moverlo para conservar la parte que prefieras.") }}</p>
      <button :disabled="outputDuration>maxDuration||!!stretchDrag" @click="$emit('preview')">{{ $t("Escuchar recorte convertido") }}</button><button @click="$emit('discard')">{{ $t("Descartar audio subido") }}</button>
    </div>
  </div>
</template>
<script>
export default {
  props:{source:Object,maxDuration:Number,busy:Boolean,disabled:Boolean},emits:['upload','range','preview','discard','editing'],
  data(){return {start:0,end:0,stretch:1,stretchDrag:null,drag:null,dragging:false,viewStart:0,viewSpan:1};},
  computed:{timelineDuration(){return Math.max(this.duration*this.stretch,this.start*this.stretch+this.maxDuration);},outputDuration(){return (this.end-this.start)*this.stretch;},selectionCapacity(){return this.maxDuration/this.stretch;},duration(){return this.source?this.source.samples.length/this.source.sampleRate:0;},minimum(){return this.source?1/this.source.sampleRate:.001;}},
  watch:{start(){this.$nextTick(()=>this.draw());},end(){this.$nextTick(()=>this.draw());},stretch(){this.$nextTick(()=>this.draw());},source(){this.initialize();},maxDuration(){if(this.source){if(this.end-this.start>this.selectionCapacity)this.fit();else this.commit();}}},mounted(){if(this.source)this.initialize();},
  methods:{
    upload(event){const file=event.target.files?.[0];event.target.value='';if(file)this.$emit('upload',file);},
    drop(event){this.dragging=false;if(this.disabled||this.busy)return;const file=event.dataTransfer.files?.[0];if(file)this.$emit('upload',file);},
    outputPercent(time){return (time-this.viewStart)/this.viewSpan*100;},percent(time){return this.outputPercent(time*this.stretch);},percentLength(time){return time/this.viewSpan*100;},
    initialize(){if(!this.source)return;this.stretch=1;this.start=0;this.end=Math.min(this.duration,Math.floor(this.selectionCapacity*this.source.sampleRate)/this.source.sampleRate);this.viewStart=0;this.viewSpan=this.timelineDuration;if(this.end/this.duration<.15)this.zoom();else this.$nextTick(()=>this.draw());this.commit();},
    waveSourceTime(time){return time/this.stretch;},
    draw(){const canvas=this.$refs.wave;if(!canvas||!this.source)return;const ctx=canvas.getContext('2d'),samples=this.source.samples,rate=this.source.sampleRate;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#4b8ec9';ctx.beginPath();for(let x=0;x<canvas.width;x++){const time=this.viewStart+x/canvas.width*this.viewSpan,next=time+this.viewSpan/canvas.width,mapped=this.waveSourceTime(time);let lo=0,hi=0;if(mapped!==null){const a=Math.floor(mapped*rate),mappedNext=this.waveSourceTime(next),b=Math.min(samples.length,Math.max(a+1,Math.floor((mappedNext===null?this.end:mappedNext)*rate)));for(let i=a;i<b;i++){lo=Math.min(lo,samples[i]||0);hi=Math.max(hi,samples[i]||0);}}ctx.moveTo(x,70-lo/32768*62);ctx.lineTo(x,70-hi/32768*62);}ctx.stroke();},

    setStart(value){if(!Number.isFinite(value))return;this.start=Math.max(Math.max(0,this.end-this.selectionCapacity),Math.min(this.end-this.minimum,value));},
    setEnd(value){if(!Number.isFinite(value))return;this.end=Math.min(this.duration,this.start+this.selectionCapacity,Math.max(this.start+this.minimum,value));},
    begin(event,kind){event.preventDefault();event.currentTarget.setPointerCapture(event.pointerId);this.drag={kind,x:event.clientX,start:this.start,end:this.end,span:this.viewSpan/this.stretch,width:this.$refs.track.getBoundingClientRect().width};},
    move(event){if(!this.drag)return;const delta=(event.clientX-this.drag.x)/this.drag.width*this.drag.span;if(this.drag.kind==='start')this.setStart(this.drag.start+delta);else if(this.drag.kind==='end')this.setEnd(this.drag.end+delta);else {const length=this.drag.end-this.drag.start;this.start=Math.max(0,Math.min(this.duration-length,this.drag.start+delta));this.end=this.start+length;}},
    finish(){if(!this.drag)return;this.drag=null;this.commit();},
    step(kind,delta){kind==='start'?this.setStart(this.start+delta):this.setEnd(this.end+delta);this.commit();},
    shift(delta){const length=this.end-this.start;this.start=Math.max(0,Math.min(this.duration-length,this.start+delta));this.end=this.start+length;this.commit();},
    updateStretch(value,origin=null){const previous=origin?.factor??this.stretch;if(origin)this.end=origin.end;this.stretch=Math.max(.1,Math.min(2,value));if(this.stretch<previous)this.end=Math.max(this.end,Math.min(this.duration,this.start+Math.floor(this.selectionCapacity*this.source.sampleRate)/this.source.sampleRate));},
    revealSelection(){this.overview();},
    setStretch(value){if(!Number.isFinite(value))return;this.updateStretch(value);this.revealSelection();this.commit();},
    beginStretch(event){event.preventDefault();this.$emit('editing');event.currentTarget.setPointerCapture(event.pointerId);this.stretchDrag={x:event.clientX,factor:this.stretch,end:this.end,length:this.end-this.start,span:this.viewSpan,width:this.$refs.track.getBoundingClientRect().width};},
    moveStretch(event){if(!this.stretchDrag)return;const drag=this.stretchDrag;this.updateStretch(drag.factor+(event.clientX-drag.x)/drag.width*drag.span/drag.length,drag);},
    finishStretch(){if(!this.stretchDrag)return;this.stretchDrag=null;this.revealSelection();this.commit();},
    fitStretch(){this.stretch=Math.max(.1,Math.min(2,this.maxDuration/(this.duration-this.start)));this.fit();this.revealSelection();},
    fit(){this.start=Math.min(this.start,Math.max(0,this.duration-this.minimum));this.end=Math.min(this.duration,this.start+Math.floor(this.selectionCapacity*this.source.sampleRate)/this.source.sampleRate);this.commit();},
    zoom(){this.viewSpan=Math.min(this.timelineDuration,Math.max(this.minimum*4,this.outputDuration*3));this.viewStart=Math.max(0,Math.min(this.timelineDuration-this.viewSpan,this.start*this.stretch-(this.viewSpan-this.outputDuration)/2));this.$nextTick(()=>this.draw());},
    overview(){this.viewStart=0;this.viewSpan=this.timelineDuration;this.$nextTick(()=>this.draw());},
    full(){this.start=0;this.end=this.duration;this.overview();this.commit();},
    commit(){this.$emit('range',{start:this.start,end:this.end,stretch:this.stretch});},
  },
};
</script>
<style scoped>
