lumn;align-items:center;gap:8px;padding:22px;border:2px dashed #92abc5;border-radius:10px;background:#f0f5fa;cursor:pointer}.audio-drop.dragging{background:#deedff;border-color:#176be0}.audio-drop span{font-size:14px;color:#516579}.audio-drop input{max-width:100%}.trim-editor{margin-top:16px;padding:18px;border:1px solid #c9d6e3;border-radius:10px;background:white}.trim-editor header{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap}.trim-editor header span{font-size:13px;color:#506477}.trim-track{position:relative;height:140px;margin:20px 12px 0;touch-action:none;background:#edf4fa;border-radius:6px;overflow:hidden}.view-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.view-controls button{font:inherit;background:#f9fbfd;padding:5px 8px;border:1px solid #bbc8d6;border-radius:5px}.view-controls label{display:flex;align-items:center;gap:8px}.view-controls input{width:180px}.trim-track canvas{width:100%;height:140px;display:block}.dim{position:absolute;top:0;bottom:0;background:#172a4070;pointer-events:none}.dim.left{left:0}.dim.right{right:0}.trim-selection{position:absolute;top:0;bottom:0;border:2px solid #176be0;box-sizing:border-box;background:#176be018;cursor:grab;touch-action:none}.trim-selection:active{cursor:grabbing}.trim-handle{position:absolute;top:-6px;height:152px;width:20px;transform:translateX(-50%);padding:0;margin:0;background:#176be0;color:white;border:2px solid white;border-radius:5px;cursor:ew-resize;touch-action:none;z-index:2}.trim-handle:focus-visible,.trim-selection:focus-visible{outline:3px solid #f4b13d}.time-axis{display:flex;justify-content:space-between;margin:6px 12px;color:#526679;font-size:12px}.trim-controls{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:16px 0}.trim-controls input{width:88px}.trim-controls button,.trim-controls input,.trim-editor>button{font:inherit;padding:7px;border:1px solid #bbc8d6;border-radius:5px;background:#f9fbfd}.trim-editor>button{margin-right:8px;cursor:pointer}.trim-controls button:disabled{opacity:.45}.trim-capacity{height:8px;background:#e4edf5;border-radius:4px;overflow:hidden}.trim-capacity span{display:block;height:100%;background:#288964}.trim-status{font-size:14px;color:#23634b}.trim-hint{font-size:14px;color:#516579}
</style>
